# CapacityRecord: dataclass + validator
from dataclasses import dataclass, field
from typing import Any

@dataclass
class Capacityrecord:
    link_id: str = None  # ID
    timestamp: str = None  # ISO 8601
    util_pct: float = None  # %
    errors_s: float = None  # Errors/sec

REQUIRED = ["link_id", "timestamp", "util_pct", "errors_s"]

def validate(rec: dict) -> list:
    errors = []
    for f in REQUIRED:
        if f not in rec or rec[f] is None:
            errors.append(f'missing: {f}')
    return errors

sample = {'link_id': 'LINK-CHI-NYC-1', 'timestamp': '2026-07-01T14:00:00Z', 'util_pct': 62.4, 'errors_s': 0}
print('validation errors:', validate(sample))
print('record ok:', not validate(sample))

